"use client";

import * as React from "react";

import { GeoLatencyMatrix, type LatencyMeasurement, type LatencyPair, type LatencyRegion } from "@/components/lumesec/geo-latency-matrix";

const regions: LatencyRegion[] = [
  { id: "eu-central", city: "Frankfurt", lat: 50.11, lon: 8.68 },
  { id: "us-east", city: "Ashburn", lat: 39.04, lon: -77.49 },
  { id: "ap-southeast", city: "Singapore", lat: 1.35, lon: 103.82 },
];

export function Example({ measurements }: { measurements: LatencyMeasurement[] }) {
  const [pair, setPair] = React.useState<LatencyPair | null>({ from: "eu-central", to: "ap-southeast" });
  return <GeoLatencyMatrix regions={regions} measurements={measurements} value={pair} onValueChange={setPair} slowMs={200} />;
}
